import {
  SUN_DIR,
  horizonColor,
  skyTopColor,
  zenithColor,
  warmColor,
  sunColor,
  cloudLitColor,
  cloudShadowColor,
} from "./theme.js";

const skyUniforms = {
  uSunDir: { value: SUN_DIR.clone() },
  uHorizon: { value: horizonColor.clone() },
  uTop: { value: skyTopColor.clone() },
  uZenith: { value: zenithColor.clone() },
  uWarm: { value: warmColor.clone() },
