    fin.position.set(x, mesh.position.y + 0.01, z);
    fin.rotation.y = yaw;
    fins.add(fin);
  }

  const group = new THREE.Group();
  group.add(mesh, stripe, disc, inner, pad, fins);
  group.userData.deckY = deckY;
  return group;
}

function finGeometry() {
  const s = new THREE.Shape();
  s.moveTo(-0.02, 0);
  s.lineTo(0.16, 0);
  s.lineTo(0.1, -0.2);
