}

function blinkAmount(t) {
  const x = (t % 3.8) / 3.8;
  const pulse = (center) => {
    const d = Math.abs(x - center);
    if (d > 0.018) return 0;
    const u = 1 - d / 0.018;
    return u * u;
  };
  return Math.max(pulse(0.22), pulse(0.27));
}

export function createSurfer() {
  const rig = new THREE.Group();
