    update(time, dt, pose, origin) {
      let born = 0;
      const quota = 5;
      for (let i = 0; i < drops.length; i++) {
        const d = drops[i];
        if (d.life <= 0) {
          if (born < quota) {
            spawn(d, pose);
            born++;
          }
          continue;
