      sprayGeo.attributes.position.needsUpdate = true;
      sprayGeo.attributes.aAlpha.needsUpdate = true;
      sprayGeo.attributes.aSize.needsUpdate = true;

      trailTimer += dt;
      if (trailTimer > 0.045) {
        trailTimer = 0;
        side.copy(pose.right);
        side.y = 0;
        if (side.lengthSq() < 1e-6) side.set(1, 0, 0);
