node --input-type=module << 'EOF'
import * as THREE from "three";
import { poseAt, sampleWater } from "./sim.js";
import { createSurfer } from "./surfer.js";

const assert = (cond, msg) => {
  if (!cond) {
    console.error("FAIL:", msg);
    process.exitCode = 1;
  } else {
    console.log("ok:", msg);
  }
};

// Normal matches finite differences.
{
  const x = 3.2, z = -4.5, t = 1.7;
  const e = 1e-3;
  const s = sampleWater(x, z, t);
  const hx = (sampleWater(x + e, z, t).h - sampleWater(x - e, z, t).h) / (2 * e);
  const hz = (sampleWater(x, z + e, t).h - sampleWater(x, z - e, t).h) / (2 * e);
  const expected = new THREE.Vector3(-hx, 1, -hz).normalize();
  assert(expected.dot(s.normal) > 0.999, `normal vs derivative ${expected.dot(s.normal).toFixed(5)}`);
}

// Travel and facing over the carve.
let minBank = Infinity, maxBank = -Infinity;
let minDot = 1;
for (let t = 1; t < 12; t += 0.25) {
  const pose = poseAt(t);
  minBank = Math.min(minBank, pose.bank);
  maxBank = Math.max(maxBank, pose.bank);
  const p0 = poseAt(t).position;
  const p1 = poseAt(t + 0.2).position;
  const d = p1.clone().sub(p0);
  d.y = 0;
  d.normalize();
  const facing = new THREE.Vector3(0, 0, -1).applyQuaternion(pose.quaternion);
  facing.y = 0;
  facing.normalize();
  minDot = Math.min(minDot, facing.dot(d));
  const up = new THREE.Vector3(0, 1, 0).applyQuaternion(pose.quaternion);
  if (up.dot(pose.normal) < 0.75) {
    assert(false, `up drifted from water at t=${t} dot=${up.dot(pose.normal).toFixed(3)}`);
  }
  const h = sampleWater(pose.position.x, pose.position.z, t).h;
  if (Math.abs(h - pose.position.y) > 1e-4) {
    assert(false, `height mismatch ${h} vs ${pose.position.y}`);
  }
}
assert(minDot > 0.92, `facing follows path (min cos ${minDot.toFixed(3)})`);
console.log(`bank range ${minBank.toFixed(3)} .. ${maxBank.toFixed(3)}`);
assert(maxBank > 0.22 && maxBank < 0.72, "bank leans but stays bounded");

const travel = poseAt(4).position.distanceTo(poseAt(2).position);
assert(travel > 8, `moves along the wave (${travel.toFixed(2)} m in 2s)`);

// Model markers. Identity pose first, then a surfing pose.
const surfer = createSurfer();
surfer.rig.updateMatrixWorld(true);
const wp = (name) => {
  const o = surfer.rig.getObjectByName(name);
  if (!o) throw new Error("missing " + name);
  return o.getWorldPosition(new THREE.Vector3());
};
const nose = wp("boardNose");
const tail = wp("boardTail");
const beakTip = wp("beakTip");
const beakBase = wp("beakBase");
const wingR = wp("wingTipR");
const wingL = wp("wingTipL");
console.log("nose", nose.toArray().map(v => v.toFixed(2)).join(","));
console.log("tail", tail.toArray().map(v => v.toFixed(2)).join(","));
console.log("beakTip", beakTip.toArray().map(v => v.toFixed(2)).join(","));
console.log("beakBase", beakBase.toArray().map(v => v.toFixed(2)).join(","));
console.log("wingR", wingR.toArray().map(v => v.toFixed(2)).join(","));
console.log("wingL", wingL.toArray().map(v => v.toFixed(2)).join(","));
assert(nose.z < tail.z - 0.5, "board nose points -Z");
assert(beakTip.z < beakBase.z - 0.4, "beak points -Z");
assert(wingR.x > 0.8, `right wing extends +X (${wingR.x.toFixed(2)})`);
assert(wingL.x < -0.8, `left wing extends -X (${wingL.x.toFixed(2)})`);
assert(beakTip.y > 0.7, `head is up (${beakTip.y.toFixed(2)})`);

// Mounted beak, after animation, agrees with travel. Cue is the tip marker,
// which the basis matrix was not built from.
for (const t of [2.2, 4.0, 6.2, 8.1, 10.4]) {
  const pose = poseAt(t);
  surfer.rig.position.copy(pose.position);
  surfer.rig.quaternion.copy(pose.quaternion);
  surfer.update(t, pose);
  surfer.rig.updateMatrixWorld(true);
  const tip = wp("beakTip");
  const base = wp("beakBase");
  const beak = tip.clone().sub(base);
  beak.y = 0;
  beak.normalize();
  const facing = new THREE.Vector3(0, 0, -1).applyQuaternion(surfer.rig.quaternion);
  facing.y = 0;
  facing.normalize();
  const dot = beak.dot(facing);
  assert(dot > 0.8, `beak faces travel at t=${t} (cos ${dot.toFixed(3)})`);

  const n = wp("boardNose");
  const tl = wp("boardTail");
  const board = n.clone().sub(tl);
  board.y = 0;
  board.normalize();
  const bdot = board.dot(facing);
  assert(bdot > 0.9, `board nose faces travel at t=${t} (cos ${bdot.toFixed(3)})`);

  // Head stays more upright than the banked body when the lean is real.
  if (Math.abs(pose.bank) > 0.18) {
    const bodyUp = new THREE.Vector3(0, 1, 0).applyQuaternion(surfer.rig.quaternion);
    const head = surfer.rig.getObjectByName("head");
    const hq = head.getWorldQuaternion(new THREE.Quaternion());
    const headUp = new THREE.Vector3(0, 1, 0).applyQuaternion(hq);
    assert(
      headUp.dot(new THREE.Vector3(0, 1, 0)) > bodyUp.dot(new THREE.Vector3(0, 1, 0)) - 0.02,
      `head levels at t=${t} head ${headUp.y.toFixed(3)} body ${bodyUp.y.toFixed(3)} bank ${pose.bank.toFixed(3)}`,
    );
  }
}

if (process.exitCode) console.error("self-test failed");
else console.log("self-test passed");
EOF
