import * as THREE from "three";
import { poseAt } from "./sim.js";
import { createSurfer } from "./surfer.js";

const surfer = createSurfer();
const pose = poseAt(8.1);
surfer.rig.quaternion.copy(pose.quaternion);
surfer.update(8.1, pose);
surfer.rig.updateMatrixWorld(true);

function boxOf(name) {
  const o = surfer.rig.getObjectByName(name);
  const box = new THREE.Box3().setFromObject(o);
  const size = box.getSize(new THREE.Vector3());
  const center = box.getCenter(new THREE.Vector3());
  console.log(name, "size", size.toArray().map(v => v.toFixed(2)).join(","), "center", center.toArray().map(v => v.toFixed(2)).join(","));
}
// wing tips
for (const name of ["wingTipR", "wingTipL"]) {
  const p = surfer.rig.getObjectByName(name).getWorldPosition(new THREE.Vector3());
  console.log(name, p.toArray().map(v => v.toFixed(2)).join(","));
}
// measure wing mesh world box: the mesh is parent of the marker
const tipR = surfer.rig.getObjectByName("wingTipR");
boxOf(tipR.parent.name || "wingMeshR");
const tipL = surfer.rig.getObjectByName("wingTipL");
// parent may be unnamed mesh
const boxR = new THREE.Box3().setFromObject(tipR.parent);
const boxL = new THREE.Box3().setFromObject(tipL.parent);
console.log("wingR box", boxR.getSize(new THREE.Vector3()).toArray().map(v=>v.toFixed(2)).join(","));
console.log("wingL box", boxL.getSize(new THREE.Vector3()).toArray().map(v=>v.toFixed(2)).join(","));
const beak = new THREE.Vector3();
const base = new THREE.Vector3();
surfer.rig.getObjectByName("beakTip").getWorldPosition(beak);
surfer.rig.getObjectByName("beakBase").getWorldPosition(base);
const dir = beak.sub(base); dir.y = 0; dir.normalize();
const facing = new THREE.Vector3(0,0,-1).applyQuaternion(surfer.rig.quaternion); facing.y=0; facing.normalize();
console.log("beak dot", dir.dot(facing).toFixed(3));
EOF

