let minDot = 1;
for (let t = 1; t < 12; t += 0.5) {
  const pose = poseAt(t);
  const p0 = pose.position.clone();
  const p1 = poseAt(t + 0.2).position;
  const d = p1.sub(p0); d.y = 0; d.normalize();
  const facing = new THREE.Vector3(0,0,-1).applyQuaternion(pose.quaternion); facing.y = 0; facing.normalize();
  minDot = Math.min(minDot, facing.dot(d));
}
if (minDot < 0.92) { console.error("facing", minDot); process.exit(1); }
const surfer = createSurfer();
const pose = poseAt(8.1);
surfer.rig.quaternion.copy(pose.quaternion);
surfer.update(8.1, pose);
surfer.rig.updateMatrixWorld(true);
const inv = surfer.rig.matrixWorld.clone().invert();
for (const name of ["wingTipR", "wingTipL"]) {
  const p = surfer.rig.getObjectByName(name).getWorldPosition(new THREE.Vector3()).applyMatrix4(inv);
  console.log(name, p.toArray().map(v => v.toFixed(2)).join(","));
}
console.log("self-test ok", minDot.toFixed(3));
